class Solution {
public:
    std::string removeStars(std::string s) {
        std::string res;
        for (char ch : s) {
            if (ch == '*') {
                res.pop_back();
            } else {
                res.push_back(ch);
            }
        }
        return res;
    }
};

class Solution {
    public String removeStars(String s) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            if (ch == '*') {
                sb.deleteCharAt(sb.length() - 1);
            } else {
                sb.append(ch);
            }
        }
        return sb.toString();
    }
}

var removeStars = function(s) {
    const st = [];
    for (const ch of s) {
        if (ch === '*') st.pop();
        else st.push(ch);
    }
    return st.join('');
};
